def investigate(context, acquire):
    hist = acquire("history")
    # Family: put in {ignore, replace, upsert}; trigger in {none, after_insert_log};
    # channel in {changes, total_changes_main, total_changes_both}.
    # We simulate each candidate and keep those matching all receipts.

    def simulate(put_mode, trigger, channel_mode, actions):
        # state: dict key->value committed; open transaction buffer per connection
        committed = {}
        # per-connection pending writes: list of (key, value) applied at commit
        pending = {"main": None, "other": None}
        # total_changes counters per connection
        tc = {"main": 0, "other": 0}
        # last changes() on main
        last_changes = 0
        # log rows count (trigger)
        log = 0
        # committed snapshot for reader: committed dict
        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                pending[conn] = []
            elif op == "commit":
                if pending[conn] is not None:
                    for (k, v) in pending[conn]:
                        committed[k] = v
                    pending[conn] = None
            elif op == "rollback":
                pending[conn] = None
            elif op == "put":
                k = act.get("key")
                v = act.get("value")
                # determine current visible value for this connection
                if pending[conn] is not None:
                    cur = None
                    for (pk, pv) in pending[conn]:
                        if pk == k:
                            cur = pv
                    if cur is None:
                        cur = committed.get(k)
                else:
                    cur = committed.get(k)
                changed = False
                if cur is None:
                    # insert
                    changed = True
                    newv = v
                else:
                    if put_mode == "ignore":
                        changed = False
                        newv = cur
                    elif put_mode == "replace":
                        changed = True
                        newv = v
                    else:  # upsert
                        changed = True
                        newv = v
                if changed:
                    if pending[conn] is not None:
                        # replace existing pending entry
                        found = False
                        for i in range(len(pending[conn])):
                            if pending[conn][i][0] == k:
                                pending[conn][i] = (k, newv)
                                found = True
                        if not found:
                            pending[conn].append((k, newv))
                    else:
                        committed[k] = newv
                    tc[conn] += 1
                    if conn == "main":
                        last_changes = 1
                    if trigger:
                        log += 1
                else:
                    if conn == "main":
                        last_changes = 0
            elif op == "update":
                k = act.get("key")
                v = act.get("value")
                if pending[conn] is not None:
                    cur = None
                    for (pk, pv) in pending[conn]:
                        if pk == k:
                            cur = pv
                    if cur is None:
                        cur = committed.get(k)
                else:
                    cur = committed.get(k)
                if cur is not None:
                    if pending[conn] is not None:
                        found = False
                        for i in range(len(pending[conn])):
                            if pending[conn][i][0] == k:
                                pending[conn][i] = (k, v)
                                found = True
                        if not found:
                            pending[conn].append((k, v))
                    else:
                        committed[k] = v
                    tc[conn] += 1
                    if conn == "main":
                        last_changes = 1
                    if trigger:
                        log += 1
                else:
                    if conn == "main":
                        last_changes = 0
            elif op == "delete":
                k = act.get("key")
                if pending[conn] is not None:
                    cur = None
                    for (pk, pv) in pending[conn]:
                        if pk == k:
                            cur = pv
                    if cur is None:
                        cur = committed.get(k)
                else:
                    cur = committed.get(k)
                if cur is not None:
                    if pending[conn] is not None:
                        newpend = []
                        for (pk, pv) in pending[conn]:
                            if pk != k:
                                newpend.append((pk, pv))
                        pending[conn] = newpend
                    else:
                        del committed[k]
                    tc[conn] += 1
                    if conn == "main":
                        last_changes = 1
                    if trigger:
                        log += 1
                else:
                    if conn == "main":
                        last_changes = 0
        if channel_mode == "changes":
            ch = last_changes
        elif channel_mode == "tc_main":
            ch = tc["main"]
        else:
            ch = tc["main"] + tc["other"]
        return ch, len(committed), sum(committed.values())

    put_modes = ["ignore", "replace", "upsert"]
    triggers = [False, True]
    channel_modes = ["changes", "tc_main", "tc_both"]

    candidates = []
    for pm in put_modes:
        for tr in triggers:
            for cm in channel_modes:
                ok = True
                for rec in hist:
                    acts = rec.get("actions", [])
                    obs = rec.get("observed", {})
                    ch, cc, cs = simulate(pm, tr, cm, acts)
                    if ch != obs.get("channel") or cc != obs.get("committed_count") or cs != obs.get("committed_sum"):
                        ok = False
                        break
                if ok:
                    candidates.append((pm, tr, cm))

    goal = context.get("goal")
    actions = context.get("actions", [])
    results = set()
    for (pm, tr, cm) in candidates:
        ch, cc, cs = simulate(pm, tr, cm, actions)
        if goal == "channel":
            results.add(ch)
        elif goal == "committed_count":
            results.add(cc)
        elif goal == "committed_sum":
            results.add(cs)
    if len(results) == 1:
        return {"value": list(results)[0], "unresolved": False}
    return {"value": None, "unresolved": True}

